(() => {
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), ui={health:$('#health-fill'),stamina:$('#stamina-fill'),hunger:$('#hunger-fill'),healthText:$('#health-text'),staminaText:$('#stamina-text'),hungerText:$('#hunger-text'),wood:$('#wood-count'),stone:$('#stone-count'),food:$('#food-count'),hide:$('#hide-count'),phase:$('#phase-label'),clock:$('#clock'),progress:$('#day-progress'),prompt:$('#prompt'),toast:$('.toast'),quest:$('#quest-title'),questCopy:$('#quest-copy'),weapon:$('#weapon-label'),boss:$('#boss-bar'),bossFill:$('#boss-health-fill'),bossLabel:$('#boss-health-label')};
const W=2600,H=2000,TAU=Math.PI*2;
let vw=innerWidth,vh=innerHeight,dpr=1,camera={x:0,y:0},state='intro',last=0,time=0,toastTimer=0,shake=0;
let player,inventory,objects,enemies,particles,decals,fireplaces,shelters,boss,nightIndex=-1,spawnTimer=0,keys={},mouse={x:0,y:0,down:false},attackCooldown=0,dodgeCooldown=0,interactTimer=0,elapsed=0,nearby=null;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.1}
function startGame(){
 state='playing';time=0;elapsed=0;nightIndex=-1;spawnTimer=3;attackCooldown=0;dodgeCooldown=0;interactTimer=0;boss=null;shake=0;
 player={x:1300,y:1510,r:17,hp:100,stamina:100,hunger:100,facing:0,invuln:0,weapon:0,hasShelter:false};
 inventory={wood:3,stone:2,food:2,hide:0};objects=[];enemies=[];particles=[];decals=[];fireplaces=[];shelters=[];
 for(let i=0;i<64;i++){let x=rand(110,W-110),y=rand(120,H-120);if(Math.hypot(x-1300,y-1510)<175||Math.hypot(x-1300,y-560)<180)continue;let r=Math.random();objects.push({type:r<.57?'tree':r<.84?'rock':'berry',x,y,r:r<.57?rand(24,38):r<.84?rand(17,25):rand(14,19),hp:r<.57?3:r<.84?2:1,seed:rand(0,100)})}
 // The shrine clearing and its ring of old standing stones.
 for(let i=0;i<7;i++){let a=i*TAU/7;objects.push({type:'rune',x:1300+Math.cos(a)*125,y:560+Math.sin(a)*95,r:16,hp:1,seed:i})}
 for(let i=0;i<22;i++)decals.push({x:rand(0,W),y:rand(0,H),r:rand(1,4),kind:Math.random()});
 inventory.wood=3;inventory.stone=2;inventory.food=2;
 $('#intro-overlay').classList.add('hidden');$('#pause-overlay').classList.add('hidden');$('#end-overlay').classList.add('hidden');ui.boss.classList.add('hidden');toast('The wild is yours. Find the shrine to the north.');refreshUI();
}
function refreshUI(){ui.health.style.width=player.hp+'%';ui.stamina.style.width=player.stamina+'%';ui.hunger.style.width=player.hunger+'%';ui.healthText.textContent=Math.ceil(player.hp);ui.staminaText.textContent=Math.ceil(player.stamina);ui.hungerText.textContent=Math.ceil(player.hunger);ui.wood.textContent=inventory.wood;ui.stone.textContent=inventory.stone;ui.food.textContent=inventory.food;ui.hide.textContent=inventory.hide;$('.craft-button[data-craft="blade"]').disabled=player.weapon>0||inventory.wood<8||inventory.stone<6;$('.craft-button[data-craft="fire"]').disabled=inventory.wood<6||inventory.stone<4;$('.craft-button[data-craft="shelter"]').disabled=inventory.wood<12||inventory.hide<4;ui.weapon.textContent=player.weapon?'RUNEBLADE':'HUNTER’S AXE'}
function nearestTarget(){let best=null,bd=74;for(const o of objects){if(o.hp<=0)continue;let d=dist(player,o);if(d<bd){bd=d;best=o}}for(const f of fireplaces){let d=dist(player,f);if(d<bd){bd=d;best={...f,type:'fire',dist:d}}}if(player.hunger<100&&dist(player,{x:930,y:950})<100&&dist(player,{x:930,y:950})<bd)best={x:930,y:950,type:'water'};return best}
function interact(){if(state!=='playing'||!nearby)return;let o=nearby;if(o.type==='fire'){player.hp=Math.min(100,player.hp+12);player.stamina=100;toast('The ember warms your bones.');return}if(o.type==='water'){player.hunger=Math.min(100,player.hunger+12);toast('Fresh spring water. You feel steadier.');return}if(o.type==='rune'){toast('Old runes. The Warden sleeps beneath this place.');return}if(o.type==='tree'){inventory.wood+=2;inventory.wood+=Math.random()<.2?1:0;damageNode(o);toast('Gathered pinewood.');}else if(o.type==='rock'){inventory.stone+=2;damageNode(o);toast('Gathered stone.');}else if(o.type==='berry'){inventory.food+=2;damageNode(o);toast('Gathered frostberries. Press C to eat.');}else return;refreshUI()}
function damageNode(o){o.hp--;for(let i=0;i<7;i++)particles.push({x:o.x,y:o.y,vx:rand(-60,60),vy:rand(-95,25),life:.55,color:o.type==='tree'?'#a78153':'#a9b5b0',size:rand(2,5)});if(o.hp<=0)o.gone=true}
function eat(){if(inventory.food<=0){toast('No food left. Find the red-berried shrubs.');return}if(player.hunger>90){toast('You are not hungry yet.');return}inventory.food--;player.hunger=Math.min(100,player.hunger+38);player.hp=Math.min(100,player.hp+5);toast('Frostberries restore your strength.');refreshUI()}
function craft(kind){if(state!=='playing')return;if(kind==='blade'){if(player.weapon){toast('Your runeblade is already forged.');return}if(inventory.wood<8||inventory.stone<6){toast('Need 8 wood and 6 stone.');return}inventory.wood-=8;inventory.stone-=6;player.weapon=1;toast('Runeblade forged. Your strikes hit harder!')}if(kind==='fire'){if(inventory.wood<6||inventory.stone<4){toast('Need 6 wood and 4 stone.');return}inventory.wood-=6;inventory.stone-=4;fireplaces.push({x:player.x,y:player.y,seed:rand(0,9)});toast('Campfire lit. Stay close to heal.')}if(kind==='shelter'){if(inventory.wood<12||inventory.hide<4){toast('Need 12 wood and 4 hide. Wolves carry hide.');return}inventory.wood-=12;inventory.hide-=4;shelters.push({x:player.x,y:player.y});player.hasShelter=true;toast('Shelter raised. A safe place in the storm.')}refreshUI()}
function attack(){if(state!=='playing'||attackCooldown>0||player.stamina<9)return;attackCooldown=.38;player.stamina-=9;let wx=mouse.x+camera.x,wy=mouse.y+camera.y;let toward=mouse.x||mouse.y?Math.atan2(wy-player.y,wx-player.x):player.facing;player.facing=toward;let reach=player.weapon?92:72,damage=player.weapon?68:34;let target=null,td=reach;for(const e of enemies){let d=dist(player,e),a=Math.atan2(e.y-player.y,e.x-player.x);if(d<td&&Math.abs(angleDiff(a,toward))<.95){td=d;target=e}}if(boss){let d=dist(player,boss),a=Math.atan2(boss.y-player.y,boss.x-player.x);if(d<td+20&&Math.abs(angleDiff(a,toward))<1.1){target=boss;td=d}}
 particles.push({kind:'swing',x:player.x,y:player.y,angle:toward,life:.2,color:player.weapon?'#d9e8ba':'#d6c08d'});if(target){target.hp-=damage;target.hit=.18;target.x+=Math.cos(toward)*21;target.y+=Math.sin(toward)*21;shake=4;for(let i=0;i<8;i++)particles.push({x:target.x,y:target.y,vx:rand(-100,100),vy:rand(-110,30),life:.4,color:target===boss?'#b8e3f3':'#d28572',size:rand(2,5)});if(target.hp<=0){if(target===boss){victory()}else{inventory.hide+=1;if(Math.random()<.38)inventory.food++;enemies=enemies.filter(e=>e!==target);toast('Draugr slain · gathered hide.');refreshUI()}}}}
function angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}
function dodge(){if(state!=='playing'||dodgeCooldown>0||player.stamina<25)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(!dx&&!dy){dx=Math.cos(player.facing);dy=Math.sin(player.facing)}let l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;player.x=clamp(player.x+dx*110,30,W-30);player.y=clamp(player.y+dy*110,30,H-30);player.invuln=.48;player.stamina-=25;dodgeCooldown=.75;for(let i=0;i<9;i++)particles.push({x:player.x-dx*rand(5,35),y:player.y-dy*rand(5,35),vx:rand(-20,20),vy:rand(-20,20),life:.35,color:'#c8d1c2',size:rand(2,5)})}
function summonEnemy(type,x,y){enemies.push({type,x,y,r:type==='wolf'?16:19,hp:type==='wolf'?58:78,max:type==='wolf'?58:78,speed:type==='wolf'?90:52,attack:0,hit:0,phase:0,seed:rand(0,9)})}
function summonBoss(){boss={x:1300,y:560,r:34,hp:530,max:530,speed:45,attack:2,windup:0,hit:0,seed:3};ui.boss.classList.remove('hidden');ui.quest.textContent='Slay the Frost Warden';ui.questCopy.textContent='The ancient shrine has awakened. End the curse.';toast('THE WARDEN AWAKENS. Hold fast!')}
function victory(){state='won';ui.boss.classList.add('hidden');$('#end-eyebrow').textContent='THE DAWN ANSWERS';$('#end-title').textContent='THE EMBER ENDURES';$('#end-copy').textContent='The Frost Warden falls. The old forest breathes again, and your saga will be told beside every hearth.';$('#end-overlay').classList.remove('hidden')}
function gameOver(){if(state!=='playing')return;state='lost';$('#end-eyebrow').textContent='THE WILD CLAIMS ITS DUE';$('#end-title').textContent='LOST TO THE LONG NIGHT';$('#end-copy').textContent='The fire has gone cold. Gather, craft, and return stronger.';$('#end-overlay').classList.remove('hidden')}

input.newString:
function gameOver(){if(state!=='playing')return;state='lost';$('#end-eyebrow').textContent='THE WILD CLAIMS ITS DUE';$('#end-title').textContent='LOST TO THE LONG NIGHT';$('#end-copy').textContent='The fire has gone cold. Gather, craft, and return stronger.';$('#end-overlay').classList.remove('hidden')}
function update(dt){
 if(state!=='playing')return;time+=dt;elapsed+=dt;attackCooldown=Math.max(0,attackCooldown-dt);dodgeCooldown=Math.max(0,dodgeCooldown-dt);player.invuln=Math.max(0,player.invuln-dt);toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');shake=Math.max(0,shake-dt*18);
 player.hunger=Math.max(0,player.hunger-dt*.105);if(player.hunger<=0)player.hp-=dt*.8;
 let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);let moving=!!(dx||dy);if(moving){let l=Math.hypot(dx,dy);dx/=l;dy/=l;player.facing=Math.atan2(dy,dx);player.x=clamp(player.x+dx*190*dt,24,W-24);player.y=clamp(player.y+dy*190*dt,24,H-24);player.stamina=Math.max(0,player.stamina-dt*2)}else player.stamina=Math.min(100,player.stamina+dt*13);
 for(const f of fireplaces)if(dist(player,f)<100){player.hp=Math.min(100,player.hp+dt*1.1);player.stamina=Math.min(100,player.stamina+dt*12)}
 camera.x=clamp(player.x-vw/2,0,W-vw);camera.y=clamp(player.y-vh/2,0,H-vh);nearby=nearestTarget();if(nearby){ui.prompt.textContent=nearby.type==='tree'?'[E] Gather pinewood':nearby.type==='rock'?'[E] Gather stone':nearby.type==='berry'?'[E] Gather frostberries':nearby.type==='water'?'[E] Drink spring water':nearby.type==='fire'?'[E] Warm yourself':'[E] Examine the runes';ui.prompt.classList.add('visible')}else ui.prompt.classList.remove('visible');if(keys.e){interactTimer-=dt;if(interactTimer<=0){interact();interactTimer=.48}}else interactTimer=0;
 let cycle=34,within=elapsed%cycle,isNight=within>=24,night=Math.floor(elapsed/cycle)+1;let currentNight=isNight?night:Math.min(3,night);ui.phase.textContent=`DAY ${Math.min(3,night)} · ${isNight?'NIGHTFALL':'MORNING'}`;ui.clock.textContent=isNight?(within<29?'21:00':'00:00'):(within<12?'06:00':'14:00');ui.progress.style.width=(within/cycle*100)+'%';ui.progress.style.background=isNight?'#87a5b0':'#dfb46b';$('#day-icon').textContent=isNight?'☾':'☼';
 if(isNight&&nightIndex!==currentNight){nightIndex=currentNight;toast(nightIndex===3?'The final night. The Warden is here.':`Night ${nightIndex}. Keep moving, keep breathing.`);if(nightIndex===3)summonBoss()}
 if(isNight){spawnTimer-=dt;if(spawnTimer<=0&&enemies.length<6){let a=rand(0,TAU),r=rand(280,470),x=clamp(player.x+Math.cos(a)*r,40,W-40),y=clamp(player.y+Math.sin(a)*r,40,H-40);summonEnemy(Math.random()<.54?'wolf':'draugr',x,y);spawnTimer=rand(4,7)}}else spawnTimer=Math.max(0,spawnTimer);
 for(const e of enemies){e.hit=Math.max(0,e.hit-dt);e.attack-=dt;let d=dist(e,player);if(d>34){let a=Math.atan2(player.y-e.y,player.x-e.x),sp=e.speed*(e.type==='wolf'&&d>130?1.18:1);e.x+=Math.cos(a)*sp*dt;e.y+=Math.sin(a)*sp*dt}if(d<43&&e.attack<=0&&player.invuln<=0){e.attack=e.type==='wolf'?1.1:1.45;player.hp-=e.type==='wolf'?9:12;player.invuln=.38;shake=3;for(let i=0;i<5;i++)particles.push({x:player.x,y:player.y,vx:rand(-70,70),vy:rand(-70,70),life:.28,color:'#d9826e',size:3})}}
 if(boss){boss.hit=Math.max(0,boss.hit-dt);boss.attack-=dt;let d=dist(boss,player);if(boss.windup>0){boss.windup-=dt;if(boss.windup<=0&&d<125&&player.invuln<=0){player.hp-=25;player.invuln=.55;shake=10;for(let i=0;i<20;i++)particles.push({x:boss.x,y:boss.y,vx:rand(-180,180),vy:rand(-170,140),life:.5,color:'#abd6e7',size:rand(2,7)})}}else if(d>56){let a=Math.atan2(player.y-boss.y,player.x-boss.x);boss.x+=Math.cos(a)*boss.speed*dt;boss.y+=Math.sin(a)*boss.speed*dt}if(d<135&&boss.attack<=0&&boss.windup<=0){boss.attack=3.1;boss.windup=.78}}
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;if(p.vx!==undefined){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy+=90*dt}if(p.life<=0)particles.splice(i,1)}
 if(player.hp<=0)gameOver();refreshUI();if(boss){ui.bossFill.style.width=Math.max(0,boss.hp/boss.max*100)+'%';ui.bossLabel.textContent=Math.max(0,Math.ceil(boss.hp/boss.max*100))+'%'}
}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);let sx=shake?rand(-shake,shake):0,sy=shake?rand(-shake,shake):0;ctx.save();ctx.translate(-camera.x+sx,-camera.y+sy);
 // Moss-dark forest floor
 ctx.fillStyle='#28352e';ctx.fillRect(0,0,W,H);
 for(const d of decals){ctx.fillStyle=d.kind>.72?'#354035':d.kind>.35?'#303d34':'#29382f';ctx.globalAlpha=.45;ctx.beginPath();ctx.ellipse(d.x,d.y,d.r*2.7,d.r,rand(0,1),0,TAU);ctx.fill()}ctx.globalAlpha=1;
 // A pale trail leads to the forgotten shrine.
 ctx.strokeStyle='#716c55';ctx.globalAlpha=.28;ctx.lineWidth=44;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(1300,1510);ctx.bezierCurveTo(1210,1320,1380,1120,1280,950);ctx.bezierCurveTo(1180,800,1260,690,1300,560);ctx.stroke();ctx.globalAlpha=1;
 // The spring is a useful landmark and a source of water.
 let water=ctx.createRadialGradient(930,950,8,930,950,95);water.addColorStop(0,'#83a697');water.addColorStop(.7,'#4e7771');water.addColorStop(1,'#344e49');ctx.fillStyle=water;ctx.beginPath();ctx.ellipse(930,950,92,59,-.3,0,TAU);ctx.fill();ctx.strokeStyle='#b9c9ad66';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#d5dfcc77';ctx.beginPath();ctx.ellipse(909,935,28,7,-.3,0,TAU);ctx.fill();
 // Woods and gatherable nodes
 for(const o of objects){if(o.gone)continue;if(o.type==='tree')drawTree(o);else if(o.type==='rock')drawRock(o);else if(o.type==='berry')drawBerry(o);else drawRune(o)}
 for(const f of fireplaces)drawFire(f);for(const s of shelters)drawShelter(s);
 for(const e of enemies)drawEnemy(e);if(boss)drawBoss(boss);drawPlayer();for(const p of particles)drawParticle(p);
 ctx.restore();drawAtmosphere();
}

