@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Marcellus&display=swap');
:root{
color-scheme:dark;--ink:#e7e5d8;--muted:#a6aaa1;--gold:#e4bb70;--panel:rgba(13,20,21,.88);--line:rgba(219,208,171,.17)}
*{
box-sizing:border-box}
html,body{
margin:0;width:100%;height:100%;overflow:hidden;background:#101719;color:var(--ink);font-family:'DM Sans',sans-serif}
button{
font:inherit;color:inherit}
#game-shell{
position:relative;width:100%;height:100%;min-height:420px;overflow:hidden;background:#18211e}
#game{
position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{
position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 48% 49%,transparent 42%,rgba(5,9,10,.37) 100%),linear-gradient(180deg,rgba(8,13,16,.47),transparent 25%,transparent 72%,rgba(7,11,12,.32))}
.topbar{
position:absolute;z-index:2;left:28px;right:28px;top:21px;height:53px;display:flex;align-items:center;gap:22px;pointer-events:none}
.brand,.day-card,.icon-button{
pointer-events:auto}
.brand{
display:flex;align-items:center;gap:10px;min-width:220px}
.brand-mark{
font-family:serif;color:#e5c27c;font-size:33px;text-shadow:0 0 20px #bc8e52}
.brand strong,.brand small{
display:block;letter-spacing:2.5px}
.brand strong{
font-family:Marcellus,serif;font-size:15px}
.brand small{
font-size:8px;color:#c2b899;margin-top:3px;letter-spacing:2px}
.day-card{
position:absolute;left:50%;transform:translateX(-50%);display:flex;gap:9px;align-items:center;padding:8px 14px;background:rgba(11,17,18,.75);border:1px solid var(--line);border-radius:4px;min-width:198px}
.sun-mark{
color:#e6c27a;font-size:22px}
.day-card small,.day-card strong{
display:block}
.day-card small{
font-size:8px;letter-spacing:1.6px;color:#c0baa5}
.day-card strong{
font-size:12px;letter-spacing:1px;margin-top:1px}
.day-track{
position:absolute;height:2px;left:0;right:0;bottom:-1px;background:#364039}
.day-track i{
height:100%;display:block;width:10%;background:#dfb46b;box-shadow:0 0 8px #f4cb7c;transition:width .2s}
.icon-button{
margin-left:auto;background:rgba(13,20,21,.75);border:1px solid var(--line);width:38px;height:38px;border-radius:4px;color:#e6d6ad;font-size:16px;cursor:pointer}
.icon-button:hover{
background:#33413c}
.vitals{
position:absolute;z-index:2;top:92px;left:30px;width:210px;padding:12px 14px;background:var(--panel);border:1px solid var(--line);border-radius:4px;display:grid;gap:9px}
.vital{
display:grid;grid-template-columns:16px 1fr 23px;align-items:center;gap:8px;font-size:12px}
.vital>span{
color:#d8b979}
.vital small{
font-size:9px;color:#d1d1c5;text-align:right}
.meter{
height:5px;border-radius:5px;background:#303b38;overflow:hidden}
.meter b{
height:100%;display:block;border-radius:4px;transition:width .2s}
.health{
background:linear-gradient(90deg,#ac5649,#e78768)}
.stamina{
background:linear-gradient(90deg,#72986c,#b3c781)}
.hunger{
background:linear-gradient(90deg,#ad8954,#e2c073)}
.quest-card{
position:absolute;z-index:2;top:92px;left:30px;transform:translateY(112px);width:260px;display:flex;gap:11px;padding:12px;background:rgba(16,23,22,.77);border-left:2px solid #d5ad68;backdrop-filter:blur(4px)}
.quest-glyph{
font-size:20px;color:#edca86}
.quest-card small,.quest-card strong{
display:block}
.quest-card small{
font-size:8px;color:#dbb971;letter-spacing:1.8px}
.quest-card strong{
font-family:Marcellus,serif;font-weight:400;font-size:14px;margin:4px 0}
.quest-card p{
margin:0;color:#b7b9af;font-size:10px;line-height:1.4}
.inventory-card{
position:absolute;z-index:2;right:24px;top:91px;width:238px;padding:14px 14px 9px;background:var(--panel);border:1px solid var(--line);border-radius:4px;box-shadow:0 10px 40px #0004;backdrop-filter:blur(6px)}
.section-heading,.craft-heading{
display:flex;justify-content:space-between;align-items:center;color:#e2c27d;font-size:9px;letter-spacing:2px}
.section-heading small{
border:1px solid #657067;border-radius:2px;padding:2px 5px;color:#d6d5c9;font-size:9px;letter-spacing:0}
.resource-grid{
display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:11px 0 15px}
.resource{
display:grid;grid-template-columns:18px 1fr auto;align-items:center;gap:6px;border:1px solid rgba(222,214,185,.1);background:rgba(255,255,255,.025);padding:6px 7px;font-size:10px;color:#c3c4b8}
.resource b{
color:#f0e5c9}
.res-icon{
text-align:center;font-size:14px}
.wood-icon{
color:#c6a56c}
.stone-icon{
color:#adbbb5}
.food-icon{
color:#d89b74}
.hide-icon{
color:#b4a1bf}
.craft-heading{
border-top:1px solid var(--line);padding-top:12px;margin-bottom:8px}
.craft-heading small{
font-size:8px;letter-spacing:.2px;color:#8f9b91}
.craft-button{
width:100%;display:flex;align-items:center;gap:9px;text-align:left;background:rgba(255,255,255,.035);border:1px solid rgba(222,214,185,.12);padding:7px 8px;margin:5px 0;cursor:pointer;transition:.15s}
.craft-button:hover:not(:disabled){
background:rgba(211,176,109,.14);border-color:#b89a5f}
.craft-button:disabled{
opacity:.42;cursor:not-allowed}
.craft-icon{
width:24px;height:24px;display:grid;place-items:center;background:rgba(196,169,112,.12);color:#e3c67d;font-size:17px}
.fire-icon{
color:#ef9c5e}
.craft-button span:nth-child(2){
flex:1}
.craft-button b,.craft-button small{
display:block}
.craft-button b{
font-size:10px;font-weight:600}
.craft-button small{
font-size:8px;color:#9da69d;margin-top:3px}
.craft-button i{
font-style:normal;color:#dfc078;font-size:7px;letter-spacing:1px}
.pack-foot{
border-top:1px solid var(--line);margin-top:10px;padding-top:8px;display:flex;justify-content:space-between;align-items:center;font-size:7px;color:#d4be85;letter-spacing:.8px}
.pack-foot button{
border:0;background:transparent;color:#d1d2c7;font-size:8px;cursor:pointer}
.pack-foot button:hover{
color:#edce8b}
kbd{
border:1px solid rgba(226,214,178,.3);border-radius:3px;padding:2px 4px;color:#e4d7b6;font:8px 'DM Sans',sans-serif;letter-spacing:.5px}
.controls-hint{
position:absolute;z-index:2;bottom:20px;left:50%;transform:translateX(-50%);white-space:nowrap;display:flex;align-items:center;gap:7px;color:#d0d0c4;font-size:9px;text-shadow:0 1px 5px #000}
.controls-hint span{
color:#ddbb76;margin:0 2px}
.interaction-prompt{
position:absolute;z-index:2;left:50%;bottom:64px;transform:translateX(-50%);padding:7px 12px;border:1px solid var(--line);background:rgba(12,18,19,.86);color:#efe2c0;font-size:11px;opacity:0;transition:opacity .15s;pointer-events:none}
.interaction-prompt.visible{
opacity:1}
.overlay{
position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:rgba(8,13,15,.53);backdrop-filter:blur(3px)}
.hidden{
display:none!important}
.intro-card,.result-card{
text-align:center;width:min(500px,calc(100vw - 36px));padding:33px 40px 30px;background:linear-gradient(145deg,rgba(23,31,30,.97),rgba(12,18,20,.96));border:1px solid rgba(216,191,133,.4);box-shadow:0 25px 100px #0009;position:relative}
.intro-card:before,.intro-card:after{
content:'';position:absolute;left:14px;right:14px;height:1px;background:linear-gradient(90deg,transparent,#ba9b62,transparent)}
.intro-card:before{
top:7px}
.intro-card:after{
bottom:7px}
.rune-line{
font-family:serif;color:#c5a36a;letter-spacing:8px;font-size:17px;margin-bottom:14px}
.eyebrow{
font-size:9px;letter-spacing:3px;color:#d4b775}
.intro-card h1{
font-family:Marcellus,serif;font-size:49px;letter-spacing:5px;font-weight:400;margin:8px 0 0;color:#eee9d9}
.intro-card h1 span{
color:#d5b875}
.subtitle{
font-size:11px;letter-spacing:5px;color:#c8c0aa;margin-top:3px}
.intro-card p,.result-card p{
font-size:12px;line-height:1.75;color:#b8beb5;margin:22px 0}
.primary-button{
background:linear-gradient(110deg,#c59d5e,#e0bd79);color:#17201d;border:0;padding:13px 20px;font-size:10px;letter-spacing:1.5px;font-weight:700;cursor:pointer;box-shadow:0 5px 20px #d0a86033}
.primary-button:hover{
filter:brightness(1.13);transform:translateY(-1px)}
.primary-button span{
font-size:15px;margin-left:10px}
.intro-note{
font-size:9px;line-height:2;color:#969f98;margin-top:20px}
.intro-note span{
color:#e0c58c}
.intro-note i{
font-style:normal;color:#8f7650;padding:0 5px}
.result-card h2{
font:400 33px Marcellus,serif;letter-spacing:2px;margin:10px 0}
.toast{
position:absolute;z-index:4;top:80px;left:50%;transform:translate(-50%,-10px);opacity:0;background:#101817eF;border:1px solid #c9a765;padding:8px 14px;color:#ead6a6;font-size:11px;transition:.2s;pointer-events:none}
.toast.show{
opacity:1;transform:translate(-50%,0)}
.boss-bar{
position:absolute;z-index:3;top:83px;left:50%;transform:translateX(-50%);width:min(380px,55vw);padding:9px 13px;background:rgba(15,18,21,.82);border:1px solid rgba(195,148,143,.46)}
.boss-bar>div{
display:flex;justify-content:space-between;font-size:9px;letter-spacing:1.4px;color:#e1c4bb;margin-bottom:6px}
.boss-bar>div b{
font-weight:500;color:#e98e7e}
.boss-bar>i{
display:block;height:5px;background:#483637}
.boss-bar>i b{
display:block;height:100%;width:100%;background:#ad514b;transition:width .2s}
.touch-controls{
display:none}
.touch-pad{
touch-action:none}
.touch-action{
touch-action:none}
.@media(max-width:760px){
.topbar{
left:12px;right:12px;top:12px}
.brand{
min-width:0}
.brand strong{
font-size:12px}
.brand small{
font-size:7px}
.brand-mark{
font-size:27px}
.day-card{
left:53%;min-width:155px;padding:6px 10px}
.day-card small{
font-size:7px}
.icon-button{
width:33px;height:33px}
.vitals{
top:75px;left:12px;width:165px;padding:9px 10px;gap:7px}
.quest-card{
top:161px;left:12px;width:186px;padding:8px;gap:7px}
.quest-card p{
font-size:9px}
.quest-card strong{
font-size:12px}
.inventory-card{
top:75px;right:10px;width:190px;padding:10px}
.resource-grid{
gap:4px;margin:8px 0 9px}
.resource{
font-size:9px;padding:5px 4px;gap:4px}
.craft-heading{
padding-top:8px;margin-bottom:5px}
.craft-button{
padding:5px 6px;gap:6px;margin:4px 0}
.craft-icon{
width:21px;height:21px}
.craft-button b{
font-size:9px}
.craft-button small{
font-size:7px}
.craft-button i{
font-size:6px}
.pack-foot{
margin-top:6px;padding-top:6px}
.controls-hint{
bottom:10px;font-size:8px;gap:4px}
.controls-hint kbd{
font-size:7px}
.interaction-prompt{
bottom:47px}
.touch-controls{
display:block;position:absolute;inset:0;pointer-events:none}
.touch-pad{
position:absolute;bottom:28px;left:20px;width:102px;height:102px;border:1px solid #ddcfaa66;border-radius:50%;background:#131b1a77;color:#d4c39488;display:grid;place-items:center;font-size:29px;pointer-events:auto}
.touch-action{
position:absolute;pointer-events:auto;border:1px solid #ddcfaa66;background:#131b1ad9;color:#ead5a3;border-radius:50%;display:grid;place-items:center}
.attack-touch{
width:65px;height:65px;right:23px;bottom:34px;font-size:23px}
.dodge-touch{
width:43px;height:43px;right:93px;bottom:77px}
.gather-touch{
width:40px;height:40px;right:96px;bottom:27px;font-size:13px}
.controls-hint{
display:none}
.intro-card{
padding:28px 20px}
.intro-card h1{
font-size:38px}
.intro-card p{
font-size:11px}
.intro-note{
font-size:8px}
.boss-bar{
top:68px;width:min(300px,50vw)}
.vignette{
background:radial-gradient(ellipse at center,transparent 35%,rgba(5,9,10,.34) 100%)}
}
@media(max-height:600px){
.inventory-card{
top:68px;padding:8px;width:200px}
.resource-grid{
margin:6px 0}
.craft-button{
padding:4px 6px;margin:3px 0}
.quest-card{
top:151px}
.vitals{
top:68px}
.controls-hint{
bottom:7px}
.intro-card{
padding:20px 30px}
.intro-card p{
margin:13px 0}
.intro-note{
margin-top:12px}
}

